/// <summary>
/// PaffH 03.02.22
/// get data from SB queue and populate it to the ds
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, btnGetQueueData), FormControlEventType::Clicked), SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void FormButtonControl1_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();
    NDXAzureServiceBusQueueInfo queueInfo;

    FormDataSource QueueInfoPAStatusChanged_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, QueueInfoPAStatusChanged));
    FormDataSource QueueInfoResponseLabelSaved_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, QueueInfoResponseLabelSaved));
    FormDataSource NDXPAWithLabelInfo_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXPAWithLabelInfo));
    NDXAzureServiceBusQueueInfo queueInfoPAStatusChanged = QueueInfoPAStatusChanged_ds.cursor();
    NDXAzureServiceBusQueueInfo queueInfoResponseLabelSaved = QueueInfoResponseLabelSaved_ds.cursor();

    //queueInfo = NDXServiceBusQueueReaderSavePALabel2NDXDatabase::GetQueueInfoStatic('palabelsaved2ndxdatabase');
    queueInfo = NDXServiceBusQueueReaderSavePALabel2NDXDatabase::GetQueueInfoStatic(NDXProdIdentControlPanelParameters::find().AzureServiceBusQueueNameLabelInfoHandshake);
    queueInfoResponseLabelSaved.setTmpData(queueInfo);

    //queueInfo = NDXServiceBusQueueReaderSavePALabel2NDXDatabase::GetQueueInfoStatic('savepalabel2ndxdatabase');
    queueInfo = NDXServiceBusQueueReaderSavePALabel2NDXDatabase::GetQueueInfoStatic(NDXProdIdentControlPanelParameters::find().AzureServiceBusQueueNameSavePALabel2NDXDatabase);
    queueInfoPAStatusChanged.setTmpData(queueInfo);

    QueueInfoPAStatusChanged_ds.executeQuery();
    QueueInfoResponseLabelSaved_ds.executeQuery();
    NDXPAWithLabelInfo_ds.executeQuery();
}

