/// <summary>
/// PaffH 11.05.22
/// create new BatchJob (LabelSaved2NDXDatabase)
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, FormButtonCreateNewBatchJobLabelSaved2NDXDatabase), FormControlEventType::Clicked), SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void FormButtonCreateNewBatchJobLabelSaved2NDXDatabase_OnClicked(FormControl sender, FormControlEventArgs e)
{
    NDXProdIdentControlPanelParameters nDXProdIdentControlPanelParameters = NDXProdIdentControlPanelParameters::find(true);
    if (nDXProdIdentControlPanelParameters.BatchHeaderRefRecIdPALabelSaved &&
        Box::yesNo("@NDX:NDXBatchJobAssignementExistsIgnore", DialogButton::No) == DialogButton::No)
    {
        return;
    }

    Args args = new Args();
    NDXBatchJobPALabelSaved2NDXDatabase nDXBatchJobPALabelSaved2NDXDatabase = NDXBatchJobPALabelSaved2NDXDatabase::construct();
    RefRecId refRecId = nDXBatchJobPALabelSaved2NDXDatabase.addTask(args);
    ttsbegin;
    nDXProdIdentControlPanelParameters.BatchHeaderRefRecIdPALabelSaved = refRecId;
    nDXProdIdentControlPanelParameters.update();
    ttscommit;

    NDXProdIdentControlPanelForm formhandler;
    FormRun thisFormRun = sender.formRun();
    formhandler = thisFormRun.parmFormhandler();
    //formhandler.parmNDXProdIdentControlPanelParameters_ds().executeQuery();
    formhandler.parmNDXProdIdentControlPanelParameters_ds().refresh();
}

