/// <summary>
/// PaffH 11.05.22
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, btnReadReturnMessageFromQueue), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed','Parameter "e"')
    ,SuppressBPWarning('BPParameterNotUsed','Parameter "sender"')]
public static void btnReadReturnMessageFromQueue_OnClicked(FormControl sender, FormControlEventArgs e)
{
    str conStr, queue;
    ResponseLabelSaved2DatabaseContract contractResponse;
    System.Exception ex;

    [conStr, queue] = NDXServiceBusQueueReaderSavePALabel2NDXDatabase::getConnectionParam();
    try
    {
        ServiceBusMessagingPALabelSaved serviceBusMessagingPALabelSaved = new ServiceBusMessagingPALabelSaved(conStr, NDXProdIdentControlPanelParameters::find().AzureServiceBusQueueNameLabelInfoHandshake);
        ServiceBusReceivedMessageValuesServiceBusMessagingPALabelSaved serviceBusReceivedMessageValuesServiceBusMessagingPALabelSaved
            = serviceBusMessagingPALabelSaved.Receive1MessageValuesD365FO(true);
        contractResponse = serviceBusReceivedMessageValuesServiceBusMessagingPALabelSaved.Contract;
        Azure.Messaging.ServiceBus.ServiceBusReceivedMessage receivedMessage = serviceBusReceivedMessageValuesServiceBusMessagingPALabelSaved.ServiceBusReceivedMessage;
        if (false)
        {
            serviceBusMessagingPALabelSaved.SendReceivedMessageToQueue(receivedMessage, queue);
        }
        //contractResponse = serviceBusMessagingPALabelSaved.Receive1MessageAsContract2(true).Contract;
        if (contractResponse != null && contractResponse.NDXProdStatusChangedGenerateTransportLabelEventContract.ProdId)
        {
            NDXPAWithLabelInfo::processFromResponseLabelSaved2DatabaseContract(contractResponse);
            NDXProdIdentControlPanel::processFromResponseLabelSaved2DatabaseContract(contractResponse);
        }
    }
    catch (ex)
    {
        error(ex.Message);
    }

}

