/// <summary>
/// PaffH 13.11.24
/// delete invalid records from Bartender onPrem
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, FormButtonDeleteInvalidBartenderRecords), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')
    ,SuppressBPWarning('BPLocalVariableNotUsed','local variable "configReader"')]
public static void FormButtonDeleteInvalidBartenderRecords_OnClicked(FormControl sender, FormControlEventArgs e)
{
    Niedax.AzureServiceBus.Models.PALabel.NDXPALabelMaintainDetailsContract detailsContract;
    System.Diagnostics.Stopwatch stopWatch = new System.Diagnostics.Stopwatch();
    stopWatch.Start();
    FormRun thisFormRun = sender.formRun();
    FormDataSource NDXProdIdentControlPanelOnPrem_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXProdIdentControlPanelOnPrem));

    NDXAzureRelayTransferPALabel nDXAzureRelayTransferPALabel = NDXAzureRelayTransferPALabel::construct();
    Niedax.AzureServiceBus.Models.PALabel.Relay.PALabelMaintainRelayContract contract = nDXAzureRelayTransferPALabel.parmMaintainRelayContract();
    contract.MaintainMode = true;
    contract.DeleteNotValidInDatabase = true;
    contract.GetDataFromDatabase = true;

    // get PA's to delete
    NDXPAWithLabelInfo nDXPAWithLabelInfo;
    NDXProdIdentControlPanel nDXProdIdentControlPanel;
    ProdTable prodTable;
    NDXProdIdentParameters nDXProdIdentParameters = NDXProdIdentParameters::find();
    container conRecId = conNull();
    while select * from nDXPAWithLabelInfo
        join prodTable where prodtable.ProdId == nDXPAWithLabelInfo.ProdId
    {
        if (prodTable.status().isAfterOrEqualTo(nDXProdIdentParameters.ProdStatusLabelErase))
        {
            while select nDXProdIdentControlPanel
                where nDXProdIdentControlPanel.ProdId == prodTable.ProdId
            {
                detailsContract = new Niedax.AzureServiceBus.Models.PALabel.NDXPALabelMaintainDetailsContract();
                detailsContract.ProdId = nDXProdIdentControlPanel.ProdId;
                detailsContract.ProdLabelId = nDXProdIdentControlPanel.ProdLabelId;
                detailsContract.DeleteLabelRecord = true;

                Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract prodIdentControlPanel = new Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract();
                prodIdentControlPanel.RecIdNDXProdIdentControlPanel = nDXProdIdentControlPanel.RecId;
                detailsContract.ProdIdentControlPanel = prodIdentControlPanel;

                contract.AddMaintainContractToList(detailsContract);
                conRecId += (nDXProdIdentControlPanel.RecId);
            }
        }
    }

    // get records to delete from NDXProdIdentControlPanel
    while select nDXProdIdentControlPanel
        where nDXProdIdentControlPanel.BTAction == NDXProdIdentBTAction::delete
    {
        if (conFind(conRecId, nDXProdIdentControlPanel.RecId))
        {
            continue;
        }
        detailsContract = new Niedax.AzureServiceBus.Models.PALabel.NDXPALabelMaintainDetailsContract();
        detailsContract.ProdLabelId = nDXProdIdentControlPanel.ProdLabelId;
        detailsContract.DeleteLabelRecord = true;

        Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract prodIdentControlPanel = new Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract();
        prodIdentControlPanel.RecIdNDXProdIdentControlPanel = nDXProdIdentControlPanel.RecId;
        detailsContract.ProdIdentControlPanel = prodIdentControlPanel;

        contract.AddMaintainContractToList(detailsContract);
    }

    nDXAzureRelayTransferPALabel.initializeAzureRelay(contract);
    nDXAzureRelayTransferPALabel.getResponseFromRelay();
    Counter counterElements = NDXPALabelAdministratedProcessing::maintainFromResponseLabelMaintainedContract(nDXAzureRelayTransferPALabel.parmResponseContract());

    stopWatch.Stop();
    System.TimeSpan timeTaken = stopWatch.Elapsed;
    Info(strFmt("@NDXBase:NDXNumberOfDataRecordsDeleted", counterElements, timeTaken.Milliseconds));
    NDXProdIdentControlPanelOnPrem_ds.executeQuery();
}

/// <summary>
/// PaffH 14.07.23
/// receive Bartender Data from onPrem
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, FormButtonGetDataFromBartenderDB), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')
    ,SuppressBPWarning('BPLocalVariableNotUsed','local variable "configReader"')]
public static void FormButtonGetDataFromBartenderDB_OnClicked(FormControl sender, FormControlEventArgs e)
{
    boolean getFromRelay = true;
    if (getFromRelay)
    {
        // Relay
        System.Diagnostics.Stopwatch stopWatch = new System.Diagnostics.Stopwatch();
        stopWatch.Start();
        FormRun thisFormRun = sender.formRun();
        FormDataSource NDXProdIdentControlPanelOnPrem_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXProdIdentControlPanelOnPrem));

        NDXAzureRelayTransferPALabel nDXAzureRelayTransferPALabel = NDXAzureRelayTransferPALabel::construct();
        Niedax.AzureServiceBus.Models.PALabel.Relay.PALabelMaintainRelayContract contract = nDXAzureRelayTransferPALabel.parmMaintainRelayContract();
        contract.MaintainMode = true;
        contract.DeleteNotValidInDatabase = true;
        contract.GetDataFromDatabase = true;
        Niedax.AzureServiceBus.Models.PALabel.NDXPALabelMaintainDetailsContract detailsContract = new Niedax.AzureServiceBus.Models.PALabel.NDXPALabelMaintainDetailsContract();
        contract.AddMaintainContractToList(detailsContract);
        nDXAzureRelayTransferPALabel.initializeAzureRelay(contract);
        nDXAzureRelayTransferPALabel.getResponseFromRelay();
        int counterElements = NDXPALabelAdministratedProcessing::fillNDXProdIdentControlPanelOnPremFromResponseLabelMaintainedContract(nDXAzureRelayTransferPALabel.parmResponseContract());
        stopWatch.Stop();
        System.TimeSpan timeTaken = stopWatch.Elapsed;
        Info(strFmt("@NDXBase:NDXNumberOfDataRecordsTransferred", counterElements, timeTaken.Milliseconds));
        NDXProdIdentControlPanelOnPrem_ds.executeQuery();
    }
    else
    {
        // Servicebus Queue
        NDXHistoryMessage message = strFmt("@NDX:NDXButtonPressed", "@NDX:NDXBTGetDataFromDB");
        NDXStepCurrent stepCurrent = 1;
        NDXHistoryLogProdIdentMaintainContract contract = NDXHistoryLogProdIdentMaintainContract::construct(stepCurrent);
        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(NDXPALabelMaintainEvent)))
        {
            IBusinessEventsConfigurationReader configReader = BusinessEventsConfigurationReader::getConfigurationReaderInstance();
            message += ' ' + "@NDXBase:NDXBusinessEventTriggered";
            contract.saveAsSuccess(message);

            NDXPALabelMaintainEvent nDXPALabelMaintainEvent = NDXPALabelMaintainEvent::construct();
            nDXPALabelMaintainEvent.parmDataFromNDXPAWithLabelInfo(false);
            nDXPALabelMaintainEvent.send();
        }
        else
        {
            message += ' ' + "@NDXBase:NDXBusinessEventNotActive";
            contract.saveAsError(message);
            Error(strFmt("@NDXBase:NDXBusinessEventNotActive2", classStr(NDXPALabelMaintainEvent)));
        }
    }
}

