/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, FormButtonCheckBTLabelForProductionOrder), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void FormButtonCheckBTLabelForProductionOrder_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormButtonControl button = sender as FormButtonControl;
    button.enabled(false);
    FormRun thisFormRun = sender.formRun();
    FormDataSource ProdTable_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, ProdTable_4));
    int recordsToProcess = max(1, ProdTable_DS.recordsMarked().lastIndex());
    if (Box::yesNo(strFmt("@NDX:NDXCheckBTLabelForProductionOrderDoCheck", recordsToProcess), DialogButton::Yes) == DialogButton::Yes)
    {
        MultiSelectionHelper helper = MultiSelectionHelper::construct();
        helper.parmDatasource(ProdTable_DS);
        ProdTable prodTableLocal = helper.getFirst();

        Dynamics.AX.Application.NDXProdStatusChangedGenerateTransportLabelEventContract contract = new Dynamics.AX.Application.NDXProdStatusChangedGenerateTransportLabelEventContract();
        new NDXBusinessEventContractInteraction().initializeContract(contract);
        while (prodTableLocal.RecId != 0)
        {
            Info(strFmt("@NDX:NDXCheckProductionLabelForProductionOrder", NDXHelperCommon::seconds2Str(), prodTableLocal.ProdId));
            NDXProdIdent::fillControlPanelFromProdTable(prodTableLocal, contract, true);
            prodTableLocal = helper.getNext();
        }
        ProdTable_DS.research(true);
    }
    button.enabled(true);
}

