/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdentControlPanel, NDXProdIdent2), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXProdIdent2_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();
    FormDataSource NDXProdIdentLabelFromProdTableView_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXProdIdentLabelFromProdTableView_6));
    NDXProdIdentLabelFromProdTableView nDXProdIdentLabelFromProdTableView = NDXProdIdentLabelFromProdTableView_DS.cursor();
